changeSet.sql:
CREATE SEQUENCE receipt_number_seq; GRANT USAGE ON SEQUENCE receipt_number_seq TO ${appDbUsername};
CREATE TABLE receipts ( id uuid NOT NULL PRIMARY KEY, created_at timestamp(6) with time zone NOT NULL, created_by varchar(255),
number varchar(32) NOT NULL, verification_code varchar(16) NOT NULL, payment_id uuid NOT NULL REFERENCES payments (id), transaction_id uuid NOT NULL REFERENCES transactions (id), buyer_user_id uuid NOT NULL REFERENCES users (id), seller_tenant_id uuid NOT NULL REFERENCES organizations (id), plot_id uuid NOT NULL REFERENCES plots (id), estate_id uuid NOT NULL REFERENCES estates (id), issued_at timestamp(6) with time zone NOT NULL,
buyer_name varchar(255) NOT NULL, seller_name varchar(255) NOT NULL, seller_rc_number varchar(64), estate_name varchar(255) NOT NULL, estate_location varchar(512), block_name varchar(255), plot_number varchar(32) NOT NULL, plot_size_sqm numeric(12, 2), is_corner boolean NOT NULL, amount numeric(19, 4) NOT NULL, currency varchar(3) NOT NULL, channel varchar(32), last4 varchar(8), payment_reference varchar(64) NOT NULL, paid_at timestamp(6) with time zone,
CONSTRAINT uq_receipts_number UNIQUE (number), CONSTRAINT uq_receipts_verification_code UNIQUE (verification_code), CONSTRAINT uq_receipts_payment UNIQUE (payment_id), CONSTRAINT chk_receipts_verification_code CHECK (verification_code ~ '^[0-9A-F]{16}$'), CONSTRAINT chk_receipts_amount CHECK (amount > 0) ); CREATE INDEX idx_receipts_buyer ON receipts (buyer_user_id, issued_at DESC); CREATE INDEX idx_receipts_transaction ON receipts (transaction_id); REVOKE UPDATE, DELETE, TRUNCATE ON receipts FROM ${appDbUsername};
COMMENT ON TABLE receipts IS 'Payment receipts issued by HomeTrue when Paystack confirms a payment (same transaction). Holds a copy of everything printed; the PDF/JPEG are drawn from it. Buyer-owned: not RLS-policied, reached by buyer_user_id or verification_code. Never updated or deleted. See AGENTS.md, "Documents".'; COMMENT ON COLUMN receipts.verification_code IS '64 random bits as 16 hex characters, printed on the receipt and in its QR code; the public verify page looks a receipt up by it. Never the id or the number, which are guessable or sequential.';
